    18	/** Quotes freight on the TransLog website. Anything unexpected, or slower than 2 seconds, means "down". */
    19	public final class TransLogClient implements CarrierGateway {
    20	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
    21	
    22	    private final String baseUrl;
    23	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
    24	
    25	    public TransLogClient(String baseUrl) {
    26	        this.baseUrl = baseUrl == null ? "" : baseUrl.replaceAll("/+$", "");
    27	    }
    28	
    29	    @Override
    30	    public Optional<Quote> quote(String zipCode, int weightGrams, String service) {
    31	        CompletableFuture<HttpResponse<String>> future = null;
    32	        try {
    33	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + URLEncoder.encode(zipCode, StandardCharsets.UTF_8)
    34	                    + "&weight_g=" + weightGrams + "&service=" + URLEncoder.encode(service, StandardCharsets.UTF_8));
    35	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
    36	            future = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
    37	            HttpResponse<String> response = future.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
    38	            if (response.statusCode() != 200) {
    39	                throw new UnavailableException("TransLog answered " + response.statusCode(), null);
    40	            }
    41	            return parse(Json.MAPPER.readTree(response.body()));
    42	        } catch (UnavailableException e) {
    43	            throw e;
    44	        } catch (InterruptedException e) {
    45	            Thread.currentThread().interrupt();
    46	            throw new UnavailableException("interrupted", e);
    47	        } catch (Exception e) {
    48	            throw new UnavailableException("TransLog failed", e);
    49	        } finally {
    50	            if (future != null) {
    51	                future.cancel(true);
    52	            }
    53	        }
    54	    }
    55	
    56	    private static Optional<Quote> parse(JsonNode body) {
    57	        if (body == null || !body.isObject()) {
    58	            throw new UnavailableException("unexpected TransLog body", null);
    59	        }
    60	        if (body.has("error")) {
    61	            if (body.get("error").isTextual() && "ZIP_NOT_SERVED".equals(body.get("error").asText())) {
    62	                return Optional.empty();
    63	            }
    64	            throw new UnavailableException("TransLog error " + body.get("error"), null);
    65	        }
    66	        JsonNode cents = body.path("price_cents");
    67	        JsonNode hours = body.path("eta_hours");
    68	        if (!cents.isIntegralNumber() || !hours.isIntegralNumber() || cents.asLong() < 0 || hours.asLong() < 0
    69	                || !hours.canConvertToInt()) {
    70	            throw new UnavailableException("unexpected TransLog quote", null);
    71	        }
    72	        BigDecimal cost = BigDecimal.valueOf(cents.asLong(), 2);
    73	        int days = (int) ((hours.asLong() + 23) / 24);
    74	        return Optional.of(new Quote(cost, days));
    75	    }
    76	}
