    30	    public Optional<Quote> quote(String zipCode, int weightGrams, String service) {
    31	        CompletableFuture<HttpResponse<String>> future = null;
    32	        try {
    33	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + URLEncoder.encode(zipCode, StandardCharsets.UTF_8)
    34	                    + "&weight_g=" + weightGrams + "&service=" + URLEncoder.encode(service, StandardCharsets.UTF_8));
    35	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
    36	            future = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
    37	            HttpResponse<String> response = future.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
    38	            if (response.statusCode() != 200) {
    39	                throw new UnavailableException("TransLog answered " + response.statusCode(), null);
    40	            }
    41	            return parse(Json.MAPPER.readTree(response.body()));
    42	        } catch (UnavailableException e) {
    43	            throw e;
    44	        } catch (InterruptedException e) {
    45	            Thread.currentThread().interrupt();
    46	            throw new UnavailableException("interrupted", e);
    47	        } catch (Exception e) {
    48	            throw new UnavailableException("TransLog failed", e);
    49	        } finally {
    50	            if (future != null) {
    51	                future.cancel(true);
    52	            }
    53	        }
    54	    }
