    56	    private static Optional<Quote> parse(JsonNode body) {
    57	        if (body == null || !body.isObject()) {
    58	            throw new UnavailableException("unexpected TransLog body", null);
    59	        }
    60	        if (body.has("error")) {
    61	            if (body.get("error").isTextual() && "ZIP_NOT_SERVED".equals(body.get("error").asText())) {
    62	                return Optional.empty();
    63	            }
    64	            throw new UnavailableException("TransLog error " + body.get("error"), null);
    65	        }
    66	        JsonNode cents = body.path("price_cents");
    67	        JsonNode hours = body.path("eta_hours");
    68	        if (!cents.isIntegralNumber() || !hours.isIntegralNumber() || cents.asLong() < 0 || hours.asLong() < 0
    69	                || !hours.canConvertToInt()) {
    70	            throw new UnavailableException("unexpected TransLog quote", null);
    71	        }
    72	        BigDecimal cost = BigDecimal.valueOf(cents.asLong(), 2);
    73	        int days = (int) ((hours.asLong() + 23) / 24);
    74	        return Optional.of(new Quote(cost, days));
    75	    }
